/* Pocket Spin: static client app. OAuth uses PKCE; no Spotify secret belongs in this file. */
const CONFIG_KEY = 'pocket-spin-config-v1';
const TOKEN_KEY = 'pocket-spin-token-v1';
const scopes = ['streaming','user-read-email','user-read-private','user-read-playback-state','user-modify-playback-state','user-read-recently-played','user-top-read'];
const demoTracks = [
  {name:'Neon Gardens', artist:'Satellite Club', album:'Midnight Circuit', duration:247000},
  {name:'Sea Glass', artist:'Eleanor Hart', album:'Low Tide', duration:218000},
  {name:'Slow Motion', artist:'Garden Club', album:'Lemon Season', duration:196000}
];
let state = { page:'home', cursor:0, stack:[], track:demoTracks[0], playing:false, progress:84000, player:null, deviceId:null, connected:false, library:demoTracks, notice:'' };
let config = JSON.parse(localStorage.getItem(CONFIG_KEY) || '{}');
let token = JSON.parse(localStorage.getItem(TOKEN_KEY) || 'null');
const $ = s => document.querySelector(s);
const screen = $('#screen');
const statusCopy = $('#statusCopy');

function escapeHtml(v='') { const d=document.createElement('div'); d.textContent=v; return d.innerHTML; }
function currentRedirect() { return location.origin + location.pathname; }
function topbar(label='') { return `<div class="topbar"><span class="tiny-brand">POCKET SPIN</span><span>${escapeHtml(label)}</span><span class="battery">▰</span></div>`; }
function menu(items, title='Music') { return `${topbar(state.connected ? 'online' : 'demo')}<div class="screen-title">${title}</div><ul class="menu-list">${items.map((item,i)=>`<li class="menu-item ${i===state.cursor?'selected':''}"><span>${item.label}</span>${item.chev!==false?'<span class="chev">›</span>':''}</li>`).join('')}</ul>`; }
function art(track) { return track.image ? `<div class="art" style="background-image:url('${track.image}');background-size:cover"><style>.art:before,.art:after{display:none}</style></div>` : '<div class="art"></div>'; }
function ms(value) { const sec=Math.floor(value/1000); return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`; }
function nowPlaying() { const t=state.track; const duration=t.duration_ms || t.duration || 1; const pos=Math.min(state.progress,duration); const percent=Math.max(0,Math.min(100,pos/duration*100)); return `${topbar('now playing')}<div class="now-playing">${art(t)}<div class="track-title">${escapeHtml(t.name)}</div><div class="artist">${escapeHtml(t.artist || t.artists?.map(a=>a.name).join(', ') || 'Unknown artist')}</div><div class="progress"><i style="width:${percent}%"></i></div><div class="times"><span>${ms(pos)}</span><span>${ms(duration)}</span></div><div class="play-state">${state.playing ? 'Ⅱ playing' : '▷ paused'}</div></div>`; }
function libraryView() { return `${topbar('library')}<div class="screen-title">Recently Played</div><div class="library">${state.library.slice(0,5).map((t,i)=>`<div class="library-row ${i===state.cursor?'selected-row':''}"><div class="thumb" ${t.image?`style="background:url('${t.image}') center/cover"`:''}></div><div class="row-copy"><b>${escapeHtml(t.name)}</b><small>${escapeHtml(t.artist || t.artists?.map(a=>a.name).join(', ') || '')}</small></div></div>`).join('')}</div>`; }
function settings() { return `${topbar('setup')}<div class="screen-title">Connect Spotify</div><div class="connect"><p>Bring your own Spotify app Client ID. Your secret is never used or stored here.</p><label class="field-label">CLIENT ID</label><input class="field" id="clientId" placeholder="paste Spotify Client ID" value="${escapeHtml(config.clientId || '')}" autocomplete="off"><label class="field-label">REDIRECT URI</label><input class="field" value="${escapeHtml(currentRedirect())}" readonly><button class="screen-action" id="connectBtn">${state.connected?'Reconnect Spotify':'Sign in with Spotify'}</button>${token?'<button class="screen-action alt" id="signoutBtn">Clear local session</button>':''}<p class="legal">Playback in this browser needs Spotify Premium and the <code>streaming</code> permission. Developer-mode apps may also require your account to be added in the Spotify dashboard.</p></div>`; }
function render() { let html; if(state.page==='now') html=nowPlaying(); else if(state.page==='library') html=libraryView(); else if(state.page==='settings') html=settings(); else { html=menu([{label:'Now Playing',page:'now'},{label:'Recently Played',page:'library'},{label:'Browse & Search',page:'browse'},{label:'Spotify Setup',page:'settings'},{label:'About Pocket Spin',page:'about'}], 'Music'); } screen.innerHTML=html; $('#connectionDot').classList.toggle('online',state.connected); statusCopy.textContent = state.connected ? 'Spotify is connected. Browse recent listening and control playback from the wheel.' : 'Demo mode is on. Set your Spotify Client ID in Settings to connect your own library.'; wireScreen(); }
function notify(msg) { const node=$('#toast'); node.textContent=msg; node.classList.add('show'); clearTimeout(notify.t); notify.t=setTimeout(()=>node.classList.remove('show'),2300); }
function wireScreen() { const c=$('#connectBtn'); if(c) c.onclick=beginLogin; const out=$('#signoutBtn'); if(out) out.onclick=()=>{localStorage.removeItem(TOKEN_KEY); token=null; state.connected=false; state.player?.disconnect(); state.player=null; notify('Local session cleared'); render();}; }
function itemsForPage() { if(state.page==='home') return [{page:'now'},{page:'library'},{page:'browse'},{page:'settings'},{page:'about'}]; if(state.page==='library') return state.library; return []; }
function move(delta) { const list=itemsForPage(); if(!list.length) return; state.cursor=(state.cursor+delta+list.length)%list.length; render(); }
function go(page) { state.stack.push({page:state.page,cursor:state.cursor}); state.page=page; state.cursor=0; render(); }
function back() { if(state.page==='home') return; const last=state.stack.pop() || {page:'home',cursor:0}; Object.assign(state,last); render(); }
function select() { if(state.page==='home') { const choice=itemsForPage()[state.cursor]; if(choice.page==='browse') return notify('Search is next in the full build — use Spotify’s own library for now.'); if(choice.page==='about') return notify('Pocket Spin • browser edition'); go(choice.page); return; } if(state.page==='library') { state.track=state.library[state.cursor]; state.progress=0; go('now'); togglePlay(); } else if(state.page==='now') togglePlay(); }
async function api(path, options={}) { await ensureToken(); const r=await fetch('https://api.spotify.com/v1'+path,{...options,headers:{Authorization:`Bearer ${token.access_token}`,...(options.headers||{})}}); if(r.status===204) return null; if(!r.ok) throw new Error(`Spotify ${r.status}`); return r.json(); }
async function ensureToken() { if(!token) throw new Error('Not signed in'); if(Date.now() < token.expires_at-60000) return; const body=new URLSearchParams({client_id:config.clientId,grant_type:'refresh_token',refresh_token:token.refresh_token}); const r=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}); if(!r.ok) throw new Error('Session expired'); const fresh=await r.json(); token={...token,...fresh,expires_at:Date.now()+fresh.expires_in*1000}; localStorage.setItem(TOKEN_KEY,JSON.stringify(token)); }
function randomVerifier() { const bytes=new Uint8Array(64); crypto.getRandomValues(bytes); return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
async function beginLogin() { const id=$('#clientId')?.value.trim(); if(!id) return notify('Paste a Spotify Client ID first'); config={clientId:id}; localStorage.setItem(CONFIG_KEY,JSON.stringify(config)); const verifier=randomVerifier(); const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)); const challenge=btoa(String.fromCharCode(...new Uint8Array(digest))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); const oauthState=randomVerifier().slice(0,24); sessionStorage.setItem('ps-verifier',verifier); sessionStorage.setItem('ps-state',oauthState); const q=new URLSearchParams({client_id:id,response_type:'code',redirect_uri:currentRedirect(),scope:scopes.join(' '),state:oauthState,code_challenge_method:'S256',code_challenge:challenge}); location.href='https://accounts.spotify.com/authorize?'+q; }
async function handleCallback() { const q=new URLSearchParams(location.search); const code=q.get('code'); if(!code) return; try { if(q.get('state')!==sessionStorage.getItem('ps-state')) throw new Error('State mismatch'); const body=new URLSearchParams({client_id:config.clientId,grant_type:'authorization_code',code,redirect_uri:currentRedirect(),code_verifier:sessionStorage.getItem('ps-verifier')}); const r=await fetch('https://accounts.spotify.com/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}); if(!r.ok) throw new Error('Could not exchange login code'); const data=await r.json(); token={...data,expires_at:Date.now()+data.expires_in*1000}; localStorage.setItem(TOKEN_KEY,JSON.stringify(token)); history.replaceState({},'',currentRedirect()); await loadSpotify(); notify('Spotify connected'); } catch(e) { notify(e.message); } }
function loadSdk() { return new Promise((resolve,reject)=>{ if(window.Spotify) return resolve(); window.onSpotifyWebPlaybackSDKReady=resolve; const s=document.createElement('script'); s.src='https://sdk.scdn.co/spotify-player.js'; s.onerror=()=>reject(new Error('Could not load Spotify player')); document.head.appendChild(s); }); }
async function loadSpotify() { if(!token) return; try { await ensureToken(); const recent=await api('/me/player/recently-played?limit=5'); state.library=recent.items.map(x=>({name:x.track.name,artist:x.track.artists.map(a=>a.name).join(', '),artists:x.track.artists,duration:x.track.duration_ms,duration_ms:x.track.duration_ms,image:x.track.album.images?.[1]?.url || x.track.album.images?.[0]?.url,uri:x.track.uri})); if(state.library[0]) state.track=state.library[0]; state.connected=true; await loadSdk(); state.player=new Spotify.Player({name:'Pocket Spin',getOAuthToken:cb=>ensureToken().then(()=>cb(token.access_token)),volume:.6}); state.player.addListener('player_state_changed',p=>{ if(!p) return; state.playing=!p.paused; state.progress=p.position; state.track={name:p.track_window.current_track.name,artist:p.track_window.current_track.artists.map(a=>a.name).join(', '),duration:p.duration,duration_ms:p.duration,image:p.track_window.current_track.album.images?.[1]?.url,uri:p.track_window.current_track.uri}; render(); }); state.player.addListener('ready',async({device_id})=>{state.deviceId=device_id; try{await api('/me/player',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({device_ids:[device_id],play:false})});}catch(e){console.warn(e);}}); state.player.addListener('account_error',()=>notify('Premium is required for browser playback.')); state.player.connect(); } catch(e) { state.connected=false; notify(e.message==='Spotify 403'?'Spotify access is unavailable for this account.':e.message); } render(); }
function togglePlay() { state.playing=!state.playing; if(state.player) state.player.togglePlay().catch(()=>notify('Playback needs Spotify Premium')); else notify(state.playing?'Demo playback started':'Demo playback paused'); render(); }
function next() { if(state.player) state.player.nextTrack(); else {const i=(demoTracks.indexOf(state.track)+1)%demoTracks.length;state.track=demoTracks[i];state.progress=0;render();} }
function previous() { if(state.player) state.player.previousTrack(); else {const i=(demoTracks.indexOf(state.track)-1+demoTracks.length)%demoTracks.length;state.track=demoTracks[i];state.progress=0;render();} }
function handleAction(action) { const actions={menu:()=>{state.page='home';state.cursor=0;state.stack=[];render();},back,next,previous,select}; if(actions[action]) actions[action](); }
// Bind directly as well as through delegation: the wheel remains dependable in embedded browsers.
document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();handleAction(button.dataset.action);}));
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action) handleAction(action);});
let lastAngle=null; const wheel=$('#wheel'); wheel.addEventListener('pointerdown',e=>{wheel.setPointerCapture(e.pointerId); lastAngle=Math.atan2(e.clientY-wheel.getBoundingClientRect().top-wheel.clientHeight/2,e.clientX-wheel.getBoundingClientRect().left-wheel.clientWidth/2);}); wheel.addEventListener('pointermove',e=>{if(lastAngle===null)return; const r=wheel.getBoundingClientRect();const a=Math.atan2(e.clientY-r.top-r.height/2,e.clientX-r.left-r.width/2);let d=(a-lastAngle)*180/Math.PI;if(d>180)d-=360;if(d<-180)d+=360;if(Math.abs(d)>16){move(d>0?1:-1);lastAngle=a;}}); wheel.addEventListener('pointerup',()=>lastAngle=null); wheel.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowRight'){move(1);e.preventDefault();}if(e.key==='ArrowUp'||e.key==='ArrowLeft'){move(-1);e.preventDefault();}if(e.key==='Enter'||e.key===' '){select();e.preventDefault();}if(e.key==='Escape')back();});
setInterval(()=>{if(state.playing&&!state.player){state.progress+=1000;if(state.progress>state.track.duration){next();}} if(state.page==='now'&&state.playing&&!state.player)render();},1000);
handleCallback().then(()=>{if(token&&!state.connected)loadSpotify();render();});
